const person = await ctx.db.get("{{param.customer_ref.ref}}", String(row["{{param.customer_ref}}"] ?? ""));
const to = person ? String(person["{{param.email_field}}"] ?? "") : "";
if (!to) { ctx.log("no email on file for this booking: confirmation not sent"); return; }
const raw = String(row["{{param.starts_field}}"] ?? "");
const when = raw ? new Date(raw).toLocaleString("en-US", { timeZone: "{{param.tz}}", weekday: "long", month: "long", day: "numeric", hour: "numeric", minute: "2-digit" }) : "soon";
const first = String(person?.["name"] ?? "").split(" ")[0] || "there";
await ctx.email({ to, subject: `You're booked for ${when}`, body: `Hi ${first},\n\nYou're all set for ${when}. We'll send a reminder the day before.\n\nNeed to change it? Sign in and open your bookings.` });
ctx.log(`confirmation sent for ${String(row["id"])}`);

const now = ctx.now().getTime();
const rows = await ctx.db.list("{{param.booking}}", { filter: [{ field: "{{param.starts_field}}", op: "gte", value: new Date(now).toISOString() }], sort: { field: "{{param.starts_field}}", dir: "asc" }, limit: 500 });
let sent = 0;
for (const b of rows) {
  if (b["reminder_sent_at"]) continue;
  if (/cancel|declin|no_show|reject/i.test(String(b["status"] ?? ""))) continue;
  const at = new Date(String(b["{{param.starts_field}}"] ?? "")).getTime();
  if (!Number.isFinite(at) || at < now || at - now > 24 * 3600 * 1000) continue;
  if (now - new Date(String(b["created_at"] ?? "")).getTime() < 3600 * 1000) continue;
  const person = await ctx.db.get("{{param.customer_ref.ref}}", String(b["{{param.customer_ref}}"] ?? ""));
  const to = person ? String(person["{{param.email_field}}"] ?? "") : "";
  if (to) {
    const when = new Date(at).toLocaleString("en-US", { timeZone: "{{param.tz}}", weekday: "long", hour: "numeric", minute: "2-digit" });
    await ctx.email({ to, subject: `See you ${when}`, body: `A quick reminder: your booking is ${when}.\n\nCan't make it? Sign in and cancel so someone else can take the spot.` });
    sent++;
  }
  await ctx.db.update("{{param.booking}}", String(b["id"]), { reminder_sent_at: ctx.now().toISOString() });
}
ctx.log(`reminders sent: ${sent}`);
